$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path
$books=@(@{profile='COMPLETATION';name='JV-комплектация 08.10.2026.xlsm'},@{profile='RETAIL';name='JV-розница 08.10.2026.xlsm'})
$selectorCapture=Get-Content (Join-Path $PSScriptRoot '..\..\docs\jv\fixtures\slider-pr11a-selector-capture.json') -Raw | ConvertFrom-Json
foreach($book in $books){
 $source=Join-Path $root $book.name
 $reference=$selectorCapture.scenarios | Where-Object { $_.profile -eq $book.profile } | Select-Object -First 1
 if(!$reference -or (Get-FileHash -Algorithm SHA256 -LiteralPath $source).Hash.ToLower() -ne $reference.sha256){throw "Source workbook identity mismatch: $source"}
}
$cases=@(
 @{id='slider_default';width=3000;height=2200;leaves=2;opening=1;h19=1;h25=$true;h27=$false;c20=2;c22=2;c24=1;c26=1},
 @{id='slider_h19_2_handle_transparent_double_lock';width=3600;height=2400;leaves=4;opening=3;h19=2;h25=$true;h27=$true;c20=1;c22=1;c24=2;c26=1},
 @{id='slider_h19_1_two_sides_no_magnet';width=2400;height=2100;leaves=3;opening=3;h19=1;h25=$false;h27=$false;c20=3;c22=3;c24=3;c26=3},
 @{id='slider_no_interlock';width=3200;height=2300;leaves=3;opening=1;h19=1;h21=$false;h25=$true;h27=$false;c20=2;c22=2;c24=1;c26=1},
 @{id='slider_h19_2_right';width=4200;height=2500;leaves=4;opening=2;h19=2;h25=$true;h27=$false;l6=$true;c20=2;c22=2;c24=4;c26=2}
)
$excel=New-Object -ComObject Excel.Application;$excel.Visible=$false;$excel.DisplayAlerts=$false;$excel.EnableEvents=$false;$excel.AskToUpdateLinks=$false;$excel.AutomationSecurity=3;$out=[System.Collections.Generic.List[object]]::new()
try {foreach($b in $books){$src=Join-Path $root $b.name;$tmp=Join-Path ([IO.Path]::GetTempPath()) ('jv-pr11g-'+[guid]::NewGuid().ToString('N')+'.xlsm');Copy-Item $src $tmp;$wb=$excel.Workbooks.Open($tmp,0,$false);try{$main=$wb.Worksheets.Item('Главная');$s=$wb.Worksheets.Item('S1');$st=$wb.Worksheets.Item('Настройки');foreach($c in $cases){$main.Range('F11').Value2=5;$main.Range('C11').Value2=$c.width;$main.Range('D11').Value2=$c.height;$main.Range('M11').Value2=$c.leaves;$main.Range('J11').Value2=$c.opening;$st.Range('H19').Value2=$c.h19;$st.Range('H21').Value2=if($c.ContainsKey('h21') -and !$c.h21){0}else{1};$st.Range('H25').Value2=if($c.h25){1}else{0};$st.Range('H27').Value2=if($c.h27){1}else{0};$st.Range('L6').Value2=if($c.ContainsKey('l6') -and $c.l6){1}else{0};$st.Range('I25').Value2=4;$st.Range('I27').Value2=4;$st.Range('I29').Value2=4;$st.Range('I31').Value2=3;$s.Range('C20').Value2=$c.c20;$s.Range('C22').Value2=$c.c22;$s.Range('C24').Value2=$c.c24;$s.Range('C26').Value2=$c.c26;$wb.Application.CalculateFullRebuild();$d=[ordered]@{};foreach($a in @('C8','C9','C10','D3','D4','D5','D6','D17','D18','D20','D22','D24','D26','D31','D32','D33','D34','D36','D37','D43','D44','D45')){$d[$a]=$s.Range($a).Value2};$q=[ordered]@{};foreach($r in 5..46){$q["K$r"]=[ordered]@{value=$s.Range("K$r").Value2;formula=$s.Range("K$r").Formula;format=$s.Range("K$r").NumberFormat}};$set=[ordered]@{};foreach($a in @('D6','D8','S7','S18','L4','L5','L6','H19','H21','H23','H25','H27')){$set[$a]=$st.Range($a).Value2};$out.Add([ordered]@{profile=$b.profile;workbook=$b.name;scenarioId=$c.id;recalc='CalculateFullRebuild';inputs=[ordered]@{width=$c.width;height=$c.height;leaves=$c.leaves;opening=$c.opening};cells=$d;settings=$set;selectorControls=[ordered]@{I25=4;C20=$c.c20;I29=4;C24=$c.c24;I31=3;C26=$c.c26};quantities=$q})}}finally{$wb.Close($false);[Runtime.InteropServices.Marshal]::ReleaseComObject($wb)|Out-Null;Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue}}}finally{$excel.Quit();[Runtime.InteropServices.Marshal]::ReleaseComObject($excel)|Out-Null;[GC]::Collect();[GC]::WaitForPendingFinalizers()}
$target=Join-Path $PSScriptRoot '..\..\docs\jv\fixtures\slider-pr11g-bom-capture.json';[IO.File]::WriteAllText([IO.Path]::GetFullPath($target),($out|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));$out|%{[pscustomobject]@{Profile=$_.profile;Scenario=$_.scenarioId;D20=$_.cells.D20;D24=$_.cells.D24;D26=$_.cells.D26;D36=$_.cells.D36;K11=$_.quantities.K11.value;K12=$_.quantities.K12.value;K25=$_.quantities.K25.value;K26=$_.quantities.K26.value;K27=$_.quantities.K27.value;K28=$_.quantities.K28.value;K35=$_.quantities.K35.value;K36=$_.quantities.K36.value;K40=$_.quantities.K40.value}}|Format-Table -AutoSize
